CREATE TABLE users (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, salt TEXT NOT NULL, password_hash TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at TEXT NOT NULL);
CREATE INDEX sessions_user ON sessions(user_id);
CREATE TABLE places (id TEXT PRIMARY KEY, name TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('restaurant','cafe')), address TEXT NOT NULL DEFAULT '', city TEXT NOT NULL DEFAULT '', lat REAL NOT NULL, lng REAL NOT NULL, source_id TEXT, created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX places_source_id ON places(source_id) WHERE source_id IS NOT NULL;
CREATE TABLE visits (id TEXT PRIMARY KEY, place_id TEXT NOT NULL REFERENCES places(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id), visited_at TEXT NOT NULL, note TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX visits_place ON visits(place_id);
CREATE TABLE ratings (place_id TEXT NOT NULL REFERENCES places(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id), service REAL NOT NULL, ambience REAL NOT NULL, value REAL NOT NULL, location REAL NOT NULL, food REAL, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(place_id,user_id));
CREATE TABLE photos (id TEXT PRIMARY KEY, visit_id TEXT NOT NULL REFERENCES visits(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id), object_key TEXT NOT NULL, content_type TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
